        "text": "وَأَحَلَّ اللَّهُ الْبَيْعَ وَحَرَّمَ الرِّبَا\n\nيحرم الاقتصاد الإسلامي الربا تحريما قطعيا، لا فرق بين القرض الإنتاجي والاستهلاكي ولا بين الفائدة البسيطة والمركبة",
