        "text": "لا يقصد بالوسط هنا أنه يتوسط مواقف الأنظمة الاقتصادية من المشكلات الاقتصادية من خلال موقفه من الملكية أو السوق أو دور الدولة، إذ لا يصح ذلك لأنه أسبق منها ظهورا. بل يراد بالوسط الخير والعدل",
