        "text": "١- عدم وجود الحافز الذاتي. فمثلاً يؤدي تلوث البيئة إلى ضرر يلحق بجميع أفراد المجتمع، ونظراً لأن كل فرد يستطيع وبشكل طبيعي أن يحصل على حاجته منها دون مقابل، فهو لا يهتم بالمحافظة على نظافة هذا المصدر، حيث يشاركه غيره في الانتفاع به. وإذا قام بعض من يهتم بذلك بدفع تكاليف تنقية الهواء فسيستفيد آخرون دون عبء إضافي عليهم، ولذلك لا يهتم هؤلاء بتوفير تلك السلعة أو الخدمة إرادياً ومن خلال السوق.\n\n٢- ضخامة حجم النفقات التي تحتاجها تنقية البيئة أو توفير الأمن، ونظراً لعدم وجود حافز الربح في مثل هذه الخدمات الأساسية فإن المنظم لا يهتم بذلك. ولذلك تقوم الدولة في ظل النظام الرأسمالي من خلال العملية السياسية التي تقوم على التصويت في البرلمانات المنتخبة نيابة عن الأفراد بالتأثير على حجم ومستوى السلع والخدمات العامة وبواسطة فرض الضرائب والرسوم على الأفراد، لتغطية نفقات توفير السلع العامة التي يعجز جهاز الأسعار عن توفيرها من خلال السوق.",
        "explanation": "",
        "source_label": "الأسس النظرية للاقتصاد الإسلامي | الفصل الثاني | ص45",
