        "cardId": "b-ch3-130",
        "text": "1- إن الاقتصاد الإسلامي ينظر إلى المال كوسيلة يستعين بها الفرد والجماعة لأداء الواجبات والفرائض، عكس النظم الأخرى التي ترى في المال غاية يستهدف الإنسان الحصول عليه وجمعه لذاته، وله فيه حق التصرف غير المحدود. وشتان بين من ينظر إليه كغاية ومن ينظر إليه كوسيلة، حيث يختلف التصرف باختلاف الهدف.\n2- الإسلام دين الفطرة ولذا أباح تملك الأموال تملكاً فردياً،\n3- اهتم الاقتصاد الإسلامي بتكوين رأس المال بالحض على الترشيد في الإنفاق والاعتدال فيه،\n4- حرص الاقتصاد الإسلامي على المحافظة على رأس المال وعدم إهداره.",
