          "فإن عجز عن الكسب إما لسبب ذاتي كالمرض أو الشيخوخة، أو خارجي كعدم توافر فرص العمل وكان فقيرا، فإن الشريعة أوجبت معونته على الأقارب،",
          "فإن عدموا فإن بيت مال الزكاة يوفر هذا المستوى،",
          "فإن لم تكف الزكاة فعلى بيت المال."
