        "text": "الأولى: علاقة التسخير، فالله سبحانه وتعالى سخر الطبيعة بما فيها من موارد ثروات للإنسان ليستعين بها على أداء وظيفته،\n\nالثانية: علاقة مسؤولية، فالإنسان مسؤول عن الاستفادة من هذه الطبيعة وحسن استغلالها وعدم إهدارها بتلويثها أو تدميرها أو غير ذلك مما يلحق الضرر بها، من أجل تعظيم المنافع المتحققة من استخدام المجتمع للموارد.",
