        "cardId": "b-ch2-080",
        "text": "يعتمد النظام الرأسمالي على آلية السوق، ومن خلال جهاز الثمن في مواجهة المشكلة الاقتصادية المرتبطة بالسلع والخدمات الخاصة، حيث تتحدد أسعار السلع والخدمات وعناصر الإنتاج وفقاً لتفاعل قوى العرض والطلب (المنتجين والمستهلكين).\n\nاعتمد النظام الاشتراكي على جهاز التخطيط المركزي كأداة وحيدة في مواجهة المشكلة الاقتصادية.\nحيث قامت الدولة بالدور الأساسي، من خلال هيئة التخطيط المركزي، بوضع خطة شاملة تحدد الأولويات من السلع والخدمات التي ترى أهميتها للمجتمع، ثم يتم توزيع الموارد على القطاعات الإنتاجية بما يتناسب مع تلك الأولويات.",
